# Ruta 25 (C2, contract 31), 22 x 32. column = i, row = j. Ruta 24's north end arrives at the south edge (j = 31); the trail winds north to the INVENTOR'S COTTAGE (the
# user's variant A "Rutas 24-25": a board-and-batten cottage with a slate roof, a radio mast, a garden fence and a mailbox) on the coast: grassy sea cliffs along the west,
# a beach and the sea (foam, 2 frames, sailboats) along the east, beach grass, tall grass (the rare dozing sprite lives here), a Hiker and a Lass, a Salve on the beach.
@map ruta_25
@size 22 32
@interior no
@area ruta_25
@bg 0
@fill grass
@spawn south 10 30 N            # arriving from Ruta 24
@spawn cottage_door 14 5 S      # in front of Teo's door
@encounters grass rate=20
  mossbud 16 19 40
  flitter 15 18 20
  muncrit 15 18 15
  jabbird 16 19 15
  quillix 15 18 5
  dozelf 16 18 5
@end
# Open ground (contract 63, normal route): a step onto plain ground (not tall grass, water, a door, a ledge, an arrow floor) rolls this table when rand8 < 4 (4/256 per step).
@open_rate 4
# Roaming wild creatures (contract 55, rollout in 63): 3 creatures of this table wander the open ground (not the tall grass); touching one starts that wild battle.
@roam 3 table=grass period=1800
@legend
  .  tile=grass
  =  tile=path
  g  tile=tall_grass
  C  tile=grass object=cliff_grass
  s  tile=sand
  W  tile=sea_tl
  w  tile=sea_o
  S  tile=sea_o object=sea_rock_a
  Z  tile=sea_o object=sailboat
  b  tile=sand object=beach_grass
  r  object=rock
  B  object=boulder
  T  object=bush
  F  object=picket_j
  M  object=mailbox
  H  object=cottage
  h  door=cottage
  G  object=sign interact=look text=ruta25.sign
  d  tile=path
  i  tile=sand item=salve
  1  npc=montanista id=t1 face=E trainer=montanista_r25 range=3 text=tr.montanista_r25.pre after=tr.montanista_r25.after
  2  npc=chica id=t2 face=W trainer=chica_r25 range=3 text=tr.chica_r25.pre after=tr.chica_r25.after
  a  tile=grass item=disc_26
  c  tile=grass item=growth_seed
  e  tile=grass item=savia
  k  tile=grass item=disc_03 hide_flag=130   # (contract 80): Disc 03 moved here from the end of Ruta 24's bridge (the recruiter's Gold Chunk is the bridge's prize now); it keeps its old pick-up flag 130
  I  tile=tall_grass hidden=savia   # hidden (contract 80, hidden items)
